with question_seed as (
  select * from jsonb_to_recordset($question_seed$[{"topic_slug":"portugues-coesao-referencia","prompt":"Em \u201cLia abriu o caderno e come\u00e7ou a escrever nele\u201d, a que se refere \u201cnele\u201d?","difficulty":1,"correct_position":2,"options":["A Lia.","Ao caderno.","\u00c0 escrita.","A uma pessoa n\u00e3o citada."],"explanation":"O pronome \u201cnele\u201d retoma o caderno, mencionado imediatamente antes."},{"topic_slug":"portugues-coesao-referencia","prompt":"Qual conectivo completa melhor a rela\u00e7\u00e3o? \u201cO \u00f4nibus atrasou; ___, chegamos depois do in\u00edcio da aula.\u201d","difficulty":2,"correct_position":3,"options":["por\u00e9m","embora","por isso","por exemplo"],"explanation":"\u201cPor isso\u201d introduz a consequ\u00eancia do atraso."},{"topic_slug":"portugues-coesao-referencia","prompt":"Qual frase evita a ambiguidade de \u201cPaula encontrou Renata quando ela sa\u00eda da biblioteca\u201d?","difficulty":3,"correct_position":1,"options":["Quando Renata sa\u00eda da biblioteca, Paula a encontrou.","Paula encontrou Renata quando ela sa\u00eda da biblioteca.","Ela encontrou Paula quando Renata sa\u00eda.","Paula e Renata sa\u00edram quando ela chegou."],"explanation":"A nova constru\u00e7\u00e3o nomeia Renata como quem sa\u00eda, deixando claro o referente."},{"topic_slug":"portugues-coesao-referencia","prompt":"Leia: \u201cO relat\u00f3rio foi entregue \u00e0 dire\u00e7\u00e3o. Esse documento re\u00fane os resultados da pesquisa.\u201d O trecho \u201cEsse documento\u201d funciona como:","difficulty":4,"correct_position":4,"options":["uma informa\u00e7\u00e3o sem referente anterior.","uma antecipa\u00e7\u00e3o do tema seguinte.","uma oposi\u00e7\u00e3o ao relat\u00f3rio.","uma retomada do relat\u00f3rio por express\u00e3o equivalente."],"explanation":"\u201cEsse documento\u201d retoma \u201cO relat\u00f3rio\u201d e mant\u00e9m a continuidade tem\u00e1tica."},{"topic_slug":"portugues-coesao-referencia","prompt":"Em \u201cA equipe reduziu o consumo de \u00e1gua. A iniciativa tamb\u00e9m diminuiu os custos\u201d, a express\u00e3o \u201cA iniciativa\u201d contribui para a coes\u00e3o porque:","difficulty":5,"correct_position":2,"options":["introduz um assunto sem rela\u00e7\u00e3o com a frase anterior.","retoma a a\u00e7\u00e3o de reduzir o consumo de \u00e1gua.","indica uma d\u00favida do autor.","substitui o sujeito por uma compara\u00e7\u00e3o."],"explanation":"A express\u00e3o resume a a\u00e7\u00e3o citada anteriormente e conecta as duas informa\u00e7\u00f5es."},{"topic_slug":"portugues-pontuacao-sentido","prompt":"Em \u201cMarina, entregue o formul\u00e1rio na secretaria\u201d, a v\u00edrgula separa:","difficulty":1,"correct_position":3,"options":["o sujeito do verbo.","o verbo de seu objeto.","o vocativo do restante da frase.","duas ora\u00e7\u00f5es subordinadas."],"explanation":"\u201cMarina\u201d \u00e9 vocativo: a pessoa a quem se dirige o pedido."},{"topic_slug":"portugues-pontuacao-sentido","prompt":"Qual sinal introduz adequadamente uma explica\u00e7\u00e3o em \u201cA regra \u00e9 simples ___ todos devem registrar a entrada\u201d?","difficulty":2,"correct_position":1,"options":[":","?","!",";"],"explanation":"Os dois-pontos podem introduzir a explica\u00e7\u00e3o da regra anunciada."},{"topic_slug":"portugues-pontuacao-sentido","prompt":"Compare \u201cN\u00e3o, espere\u201d e \u201cN\u00e3o espere\u201d. A v\u00edrgula altera o sentido porque:","difficulty":3,"correct_position":4,"options":["marca uma pergunta indireta.","indica que o sujeito foi omitido.","transforma o verbo em passado.","na primeira frase, \u201cn\u00e3o\u201d responde a algo; na segunda, nega o pedido de esperar."],"explanation":"A pontua\u00e7\u00e3o separa \u201cN\u00e3o\u201d como resposta e muda a instru\u00e7\u00e3o dada."},{"topic_slug":"portugues-pontuacao-sentido","prompt":"Em \u201cO laborat\u00f3rio foi fechado; os equipamentos passar\u00e3o por revis\u00e3o\u201d, o ponto e v\u00edrgula:","difficulty":4,"correct_position":2,"options":["indica que a segunda ora\u00e7\u00e3o \u00e9 uma pergunta.","separa duas ora\u00e7\u00f5es relacionadas, com pausa maior que a v\u00edrgula.","substitui obrigatoriamente os dois-pontos.","mostra que a segunda ideia contradiz a primeira."],"explanation":"As ora\u00e7\u00f5es s\u00e3o independentes, mas relacionadas; o ponto e v\u00edrgula marca essa pausa intermedi\u00e1ria."},{"topic_slug":"portugues-pontuacao-sentido","prompt":"Em \u201cOs estudantes, que revisaram o cap\u00edtulo, resolveram a atividade\u201d, as v\u00edrgulas sugerem que:","difficulty":5,"correct_position":3,"options":["somente alguns estudantes revisaram o cap\u00edtulo.","a revis\u00e3o ocorreu depois da atividade.","todos os estudantes mencionados revisaram o cap\u00edtulo.","o trecho entre v\u00edrgulas \u00e9 uma fala direta."],"explanation":"A ora\u00e7\u00e3o explicativa entre v\u00edrgulas acrescenta uma informa\u00e7\u00e3o sobre o grupo todo."},{"topic_slug":"portugues-variacao-registros","prompt":"Uma pessoa usa g\u00edrias ao conversar com amigos e linguagem mais formal em uma entrevista. Isso exemplifica:","difficulty":1,"correct_position":2,"options":["erro obrigat\u00f3rio de concord\u00e2ncia.","adequa\u00e7\u00e3o do registro \u00e0 situa\u00e7\u00e3o comunicativa.","mudan\u00e7a de idioma sem motivo.","aus\u00eancia de varia\u00e7\u00e3o lingu\u00edstica."],"explanation":"Falantes ajustam o registro ao interlocutor, ao objetivo e ao contexto."},{"topic_slug":"portugues-variacao-registros","prompt":"A pron\u00fancia de uma mesma palavra pode mudar entre regi\u00f5es. Essa diferen\u00e7a \u00e9:","difficulty":2,"correct_position":4,"options":["necessariamente falta de estudo.","uma prova de que uma regi\u00e3o fala sem regras.","um problema que a escrita deve eliminar.","uma varia\u00e7\u00e3o lingu\u00edstica regional."],"explanation":"Pron\u00fancia e vocabul\u00e1rio podem variar regionalmente sem tornar uma variedade inferior."},{"topic_slug":"portugues-variacao-registros","prompt":"Em um relat\u00f3rio cient\u00edfico, a escolha de termos precisos e de constru\u00e7\u00f5es formais atende principalmente:","difficulty":3,"correct_position":1,"options":["ao g\u00eanero e \u00e0 finalidade do texto.","\u00e0 obriga\u00e7\u00e3o de evitar qualquer opini\u00e3o.","\u00e0 ideia de que s\u00f3 existe uma variedade correta em todos os contextos.","\u00e0 necessidade de imitar a fala cotidiana."],"explanation":"O registro formal \u00e9 adequado \u00e0s conven\u00e7\u00f5es e ao prop\u00f3sito do relat\u00f3rio."},{"topic_slug":"portugues-variacao-registros","prompt":"Uma campanha escolar valoriza diferentes sotaques e modos de falar. A mensagem combate:","difficulty":4,"correct_position":3,"options":["a leitura em voz alta.","o uso de linguagem formal em documentos.","o preconceito lingu\u00edstico contra determinadas variedades.","a aprendizagem de novas palavras."],"explanation":"Desqualificar uma variedade por seu sotaque ou origem \u00e9 preconceito lingu\u00edstico."},{"topic_slug":"portugues-variacao-registros","prompt":"Um estudante escreve \u201cA gente fomos\u201d em di\u00e1logo de personagem e usa \u201cN\u00f3s fomos\u201d na narra\u00e7\u00e3o formal. Para analisar as escolhas, \u00e9 mais adequado:","difficulty":5,"correct_position":2,"options":["classificar toda forma coloquial como sem sentido.","considerar personagem, situa\u00e7\u00e3o e efeito de autenticidade, al\u00e9m da norma prevista para cada trecho.","afirmar que as duas formas s\u00e3o id\u00eanticas em qualquer contexto.","ignorar quem fala e a finalidade do texto."],"explanation":"A an\u00e1lise considera variedade, contexto e conven\u00e7\u00e3o do g\u00eanero, sem confundir registro com capacidade lingu\u00edstica."},{"topic_slug":"literatura-realismo-naturalismo","prompt":"Uma narrativa realista costuma privilegiar:","difficulty":1,"correct_position":1,"options":["observa\u00e7\u00e3o cr\u00edtica das rela\u00e7\u00f5es sociais e das motiva\u00e7\u00f5es das personagens.","her\u00f3is idealizados e cen\u00e1rios sempre fant\u00e1sticos.","explica\u00e7\u00f5es exclusivamente mitol\u00f3gicas.","a aus\u00eancia de conflitos humanos."],"explanation":"O Realismo observa criticamente a sociedade e constr\u00f3i personagens psicologicamente complexas."},{"topic_slug":"literatura-realismo-naturalismo","prompt":"No Naturalismo, a influ\u00eancia do meio social e das condi\u00e7\u00f5es materiais sobre as personagens tende a ser:","difficulty":2,"correct_position":3,"options":["ignorada em favor do destino m\u00e1gico.","apresentada apenas como decora\u00e7\u00e3o.","explorada como for\u00e7a que condiciona comportamentos.","substitu\u00edda por aventuras de cavalaria."],"explanation":"O Naturalismo frequentemente destaca ambiente e condi\u00e7\u00f5es sociais como fatores que influenciam a conduta."},{"topic_slug":"literatura-realismo-naturalismo","prompt":"Um narrador descreve a hipocrisia de uma elite por meio de ironia e contradi\u00e7\u00f5es das personagens. Esse recurso se associa especialmente:","difficulty":3,"correct_position":4,"options":["\u00e0 epopeia medieval.","ao sentimentalismo indianista.","ao teatro religioso colonial.","\u00e0 cr\u00edtica social realista."],"explanation":"A ironia pode expor contradi\u00e7\u00f5es e criticar valores sociais, caracter\u00edstica comum do Realismo."},{"topic_slug":"literatura-realismo-naturalismo","prompt":"Uma obra naturalista apresenta moradia insalubre, explora\u00e7\u00e3o do trabalho e conflitos ligados \u00e0 pobreza. A leitura mais consistente \u00e9 que:","difficulty":4,"correct_position":2,"options":["as personagens agem sem influ\u00eancia do contexto.","o ambiente e as condi\u00e7\u00f5es de vida participam da constru\u00e7\u00e3o dos conflitos.","o texto evita qualquer observa\u00e7\u00e3o social.","a pobreza \u00e9 tratada como tema apenas ornamental."],"explanation":"O Naturalismo enfatiza condi\u00e7\u00f5es ambientais e sociais na representa\u00e7\u00e3o dos conflitos."},{"topic_slug":"literatura-realismo-naturalismo","prompt":"Ao comparar narradores realistas e naturalistas, qual afirma\u00e7\u00e3o \u00e9 mais precisa?","difficulty":5,"correct_position":3,"options":["Ambos precisam idealizar a sociedade para serem considerados romances.","O Naturalismo elimina personagens e descreve somente paisagens.","Podem compartilhar cr\u00edtica social, mas o Naturalismo acentua explica\u00e7\u00f5es ligadas ao meio e a condi\u00e7\u00f5es materiais.","O Realismo se limita a narrativas mitol\u00f3gicas."],"explanation":"As escolas t\u00eam aproxima\u00e7\u00f5es, mas o Naturalismo tende a acentuar determinantes do meio, enquanto o Realismo amplia a an\u00e1lise psicol\u00f3gica e social."},{"topic_slug":"literatura-modernismo-brasileiro","prompt":"A Semana de Arte Moderna de 1922 ficou associada \u00e0:","difficulty":1,"correct_position":2,"options":["defesa de regras acad\u00eamicas como \u00fanicas formas leg\u00edtimas de arte.","busca por renova\u00e7\u00e3o est\u00e9tica e questionamento de padr\u00f5es acad\u00eamicos.","proibi\u00e7\u00e3o de temas brasileiros.","substitui\u00e7\u00e3o da literatura por textos cient\u00edficos."],"explanation":"O evento simboliza a ruptura modernista com padr\u00f5es acad\u00eamicos e a experimenta\u00e7\u00e3o art\u00edstica."},{"topic_slug":"literatura-modernismo-brasileiro","prompt":"Em poemas modernistas, versos livres e vocabul\u00e1rio cotidiano podem ser usados para:","difficulty":2,"correct_position":4,"options":["impedir qualquer interpreta\u00e7\u00e3o.","reproduzir obrigatoriamente a m\u00e9trica cl\u00e1ssica.","evitar refer\u00eancias \u00e0 realidade brasileira.","ampliar a experimenta\u00e7\u00e3o e aproximar o poema de novas experi\u00eancias."],"explanation":"A liberdade formal permitiu explorar ritmos, registros e temas contempor\u00e2neos."},{"topic_slug":"literatura-modernismo-brasileiro","prompt":"Um poema reelabora uma lenda ind\u00edgena com humor e linguagem urbana. Essa combina\u00e7\u00e3o pode expressar:","difficulty":3,"correct_position":1,"options":["apropria\u00e7\u00e3o cr\u00edtica de refer\u00eancias culturais para discutir uma identidade brasileira plural.","rejei\u00e7\u00e3o de qualquer cultura local.","retorno obrigat\u00f3rio ao modelo \u00e9pico europeu.","desinteresse pela linguagem."],"explanation":"A reelabora\u00e7\u00e3o de refer\u00eancias diversas pode questionar modelos \u00fanicos de identidade nacional."},{"topic_slug":"literatura-modernismo-brasileiro","prompt":"Um texto modernista mistura fala popular, refer\u00eancias hist\u00f3ricas e imagens inesperadas. A an\u00e1lise mais adequada \u00e9:","difficulty":4,"correct_position":3,"options":["considerar a mistura um defeito automaticamente.","buscar apenas uma moral expl\u00edcita e ignorar a forma.","observar como a combina\u00e7\u00e3o de registros e imagens cria sentidos e desafia conven\u00e7\u00f5es.","supor que o texto n\u00e3o possui organiza\u00e7\u00e3o."],"explanation":"A experimenta\u00e7\u00e3o modernista articula forma e conte\u00fado para criar efeitos e questionar conven\u00e7\u00f5es."},{"topic_slug":"literatura-modernismo-brasileiro","prompt":"Um poema rompe a sintaxe convencional, mas repete imagens de cidade e m\u00e1quina. Essa escolha pode ser entendida como:","difficulty":5,"correct_position":2,"options":["uma tentativa de esconder que n\u00e3o h\u00e1 assunto.","uma forma que acompanha a experi\u00eancia de moderniza\u00e7\u00e3o e produz ritmo ou estranhamento.","uma regra fixa de todos os poemas anteriores a 1922.","uma prova de que o texto n\u00e3o \u00e9 liter\u00e1rio."],"explanation":"A forma fragmentada pode dialogar com mudan\u00e7as urbanas e tecnol\u00f3gicas, produzindo efeitos de sentido."},{"topic_slug":"literatura-poesia-voz-imagens","prompt":"Em um poema, o \u201ceu l\u00edrico\u201d \u00e9:","difficulty":1,"correct_position":4,"options":["sempre o autor falando fatos biogr\u00e1ficos literalmente.","a pessoa que l\u00ea o poema em voz alta.","o personagem principal de qualquer romance.","a voz constru\u00edda no poema que expressa uma perspectiva."],"explanation":"O eu l\u00edrico \u00e9 uma voz textual e n\u00e3o deve ser automaticamente confundido com o autor."},{"topic_slug":"literatura-poesia-voz-imagens","prompt":"A repeti\u00e7\u00e3o de um mesmo som consonantal em v\u00e1rios versos pode produzir:","difficulty":2,"correct_position":1,"options":["alitera\u00e7\u00e3o e efeito sonoro.","uma compara\u00e7\u00e3o obrigat\u00f3ria.","uma mudan\u00e7a de narrador.","um argumento de autoridade."],"explanation":"A repeti\u00e7\u00e3o de sons consonantais \u00e9 alitera\u00e7\u00e3o e pode refor\u00e7ar o ritmo ou uma imagem."},{"topic_slug":"literatura-poesia-voz-imagens","prompt":"Em \u201co rel\u00f3gio mastigava as horas\u201d, atribui-se uma a\u00e7\u00e3o humana ou animal a um objeto. O recurso \u00e9:","difficulty":3,"correct_position":3,"options":["eufemismo.","meton\u00edmia.","personifica\u00e7\u00e3o.","paradoxo."],"explanation":"O rel\u00f3gio recebe a a\u00e7\u00e3o de \u201cmastigar\u201d, caracterizando personifica\u00e7\u00e3o."},{"topic_slug":"literatura-poesia-voz-imagens","prompt":"Um poema alterna versos curtos e longos nos trechos de calma e de urg\u00eancia. Para interpretar o efeito, conv\u00e9m:","difficulty":4,"correct_position":2,"options":["contar apenas as palavras desconhecidas.","relacionar ritmo e extens\u00e3o dos versos ao movimento sugerido pelo poema.","presumir que o tamanho dos versos \u00e9 acidental.","ignorar pausas e sonoridade."],"explanation":"A disposi\u00e7\u00e3o dos versos pode refor\u00e7ar o ritmo e a experi\u00eancia expressa."},{"topic_slug":"literatura-poesia-voz-imagens","prompt":"Uma imagem po\u00e9tica associa \u201cra\u00edzes\u201d \u00e0 mem\u00f3ria familiar sem falar de plantas. A leitura mais sustentada \u00e9 que \u201cra\u00edzes\u201d funciona como:","difficulty":5,"correct_position":4,"options":["termo cient\u00edfico sem sentido figurado.","ironia que sempre significa o contr\u00e1rio.","hip\u00e9rbole num\u00e9rica.","met\u00e1fora de origem e v\u00ednculo com a hist\u00f3ria familiar."],"explanation":"O contexto permite interpretar \u201cra\u00edzes\u201d figurativamente como origem e pertencimento."},{"topic_slug":"ingles-modal-verbs","prompt":"Choose the best completion: \u201cYou ___ wear a helmet when riding a bicycle.\u201d","difficulty":1,"correct_position":2,"options":["might to","should","are","did"],"explanation":"\u201cShould\u201d expresses sensible advice or recommendation."},{"topic_slug":"ingles-modal-verbs","prompt":"A sign says: \u201cVisitors must show identification.\u201d What does \u201cmust\u201d express here?","difficulty":2,"correct_position":4,"options":["permission to leave.","a past habit.","a personal preference.","an obligation."],"explanation":"In this instruction, \u201cmust\u201d signals a requirement."},{"topic_slug":"ingles-modal-verbs","prompt":"Complete the sentence: \u201cIt is cloudy, but it ___ rain later; the forecast is uncertain.\u201d","difficulty":3,"correct_position":1,"options":["might","must to","shouldn\u2019t to","has"],"explanation":"\u201cMight\u201d expresses a possibility rather than certainty."},{"topic_slug":"ingles-modal-verbs","prompt":"A student says, \u201cI can solve the first part, but I can\u2019t explain the final step.\u201d What does \u201ccan\u2019t\u201d indicate?","difficulty":4,"correct_position":3,"options":["a rule imposed by someone else.","a future plan.","lack of ability in that situation.","a completed action."],"explanation":"\u201cCan\u2019t\u201d indicates inability or lack of capacity in the context."},{"topic_slug":"ingles-modal-verbs","prompt":"A museum notice says, \u201cYou needn\u2019t book in advance, but you must arrive before 5 p.m.\u201d Which interpretation is correct?","difficulty":5,"correct_position":2,"options":["Booking is compulsory and arrival time is optional.","Booking is optional, while arriving before 5 p.m. is required.","Both booking and arrival time are suggestions.","Visitors are prohibited before 5 p.m."],"explanation":"\u201cNeedn\u2019t\u201d removes the obligation to book; \u201cmust\u201d establishes the arrival requirement."},{"topic_slug":"ingles-connectors","prompt":"Choose the connector: \u201cThe road was closed, ___ we took another route.\u201d","difficulty":1,"correct_position":3,"options":["although","because","so","unless"],"explanation":"\u201cSo\u201d introduces the result of the road closure."},{"topic_slug":"ingles-connectors","prompt":"In \u201cAlthough the task was difficult, the group finished it\u201d, \u201calthough\u201d introduces:","difficulty":2,"correct_position":1,"options":["a contrast between an obstacle and an unexpected result.","a reason for finishing.","a sequence of instructions.","an example."],"explanation":"\u201cAlthough\u201d marks concession: the difficulty did not prevent completion."},{"topic_slug":"ingles-connectors","prompt":"Complete: \u201cThe experiment was repeated ___ the first results were inconsistent.\u201d","difficulty":3,"correct_position":4,"options":["therefore","however","for instance","because"],"explanation":"\u201cBecause\u201d introduces the reason for repeating the experiment."},{"topic_slug":"ingles-connectors","prompt":"A paragraph presents a claim, ___ gives two examples and ___ states a conclusion. Which sequence best signals the relations?","difficulty":4,"correct_position":2,"options":["however / because","then / finally","unless / meanwhile","although / despite"],"explanation":"\u201cThen\u201d advances the explanation; \u201cfinally\u201d introduces its closing step."},{"topic_slug":"ingles-connectors","prompt":"\u201cMany students prefer digital notes. Nevertheless, printed pages can help some readers focus.\u201d The connector signals:","difficulty":5,"correct_position":3,"options":["a cause that proves the first claim.","a restatement with identical meaning.","a qualification or contrast to the preceding idea.","a chronological sequence."],"explanation":"\u201cNevertheless\u201d introduces a contrasting qualification."},{"topic_slug":"ingles-cognates-context","prompt":"In \u201cThe hospital opened a new unit for children\u201d, the word \u201chospital\u201d is a:","difficulty":1,"correct_position":2,"options":["false cognate meaning hotel.","cognate with a similar meaning in Portuguese.","verb in the past tense.","word meaning school."],"explanation":"\u201cHospital\u201d has a similar form and meaning in English and Portuguese."},{"topic_slug":"ingles-cognates-context","prompt":"In \u201cThe lecture was long, but the examples made it interesting\u201d, \u201clecture\u201d means:","difficulty":2,"correct_position":4,"options":["a written letter.","a leisure activity.","a test score.","an oral lesson or talk."],"explanation":"The context of examples and interest points to a class talk or lecture."},{"topic_slug":"ingles-cognates-context","prompt":"In \u201cThe fabric is light, so it is comfortable in summer\u201d, \u201clight\u201d most likely means:","difficulty":3,"correct_position":1,"options":["not heavy.","bright in color only.","not serious.","a source of electricity."],"explanation":"The clothing and summer context indicates low weight or thinness."},{"topic_slug":"ingles-cognates-context","prompt":"A notice reads \u201cActually, the library closes at 6 p.m.\u201d Why is translating \u201cactually\u201d as \u201catualmente\u201d risky?","difficulty":4,"correct_position":3,"options":["because both words always mean \u201cin fact\u201d.","because \u201cactually\u201d is a noun here.","because \u201cactually\u201d usually means \u201cin fact\u201d, while \u201catualmente\u201d means \u201ccurrently\u201d.","because the sentence has no time reference."],"explanation":"\u201cActually\u201d is a false cognate in many contexts; here it introduces a correction."},{"topic_slug":"ingles-cognates-context","prompt":"In \u201cThe researchers observed a gradual decline in the number of insects\u201d, what does \u201cdecline\u201d mean?","difficulty":5,"correct_position":2,"options":["a celebration.","a decrease.","a prediction of growth.","a method of observation."],"explanation":"\u201cA decline in the number\u201d means that the number decreased."},{"topic_slug":"artes-elementos-visuais","prompt":"Em uma composi\u00e7\u00e3o visual, a diferen\u00e7a entre \u00e1reas claras e escuras cria principalmente:","difficulty":1,"correct_position":4,"options":["uma rima sonora.","uma sequ\u00eancia cronol\u00f3gica.","uma regra gramatical.","contraste e destaque."],"explanation":"A oposi\u00e7\u00e3o entre claro e escuro pode criar contraste e direcionar o olhar."},{"topic_slug":"artes-elementos-visuais","prompt":"Uma obra usa linhas diagonais repetidas para sugerir velocidade. O elemento visual enfatizado \u00e9:","difficulty":2,"correct_position":1,"options":["linha e dire\u00e7\u00e3o.","volume real.","perspectiva sonora.","ritmo verbal."],"explanation":"Linhas diagonais podem criar dire\u00e7\u00e3o e sensa\u00e7\u00e3o de movimento."},{"topic_slug":"artes-elementos-visuais","prompt":"Uma paleta com cores complementares intensas tende a produzir:","difficulty":3,"correct_position":3,"options":["aus\u00eancia de contraste crom\u00e1tico.","uma escala de cinza obrigat\u00f3ria.","contraste visual forte entre as cores escolhidas.","uma imagem necessariamente monocrom\u00e1tica."],"explanation":"Cores complementares podem intensificar o contraste quando usadas lado a lado."},{"topic_slug":"artes-elementos-visuais","prompt":"Em uma fotografia, o objeto principal aparece n\u00edtido e o fundo desfocado. Esse recurso ajuda a:","difficulty":4,"correct_position":2,"options":["eliminar qualquer hierarquia visual.","destacar o objeto e organizar a aten\u00e7\u00e3o do observador.","provar que a foto foi feita sem inten\u00e7\u00e3o.","substituir a composi\u00e7\u00e3o por uma legenda."],"explanation":"A diferen\u00e7a de foco separa figura e fundo e dirige a aten\u00e7\u00e3o ao assunto principal."},{"topic_slug":"artes-elementos-visuais","prompt":"Uma instala\u00e7\u00e3o combina luz, sombra e a circula\u00e7\u00e3o do p\u00fablico pelo espa\u00e7o. Para interpret\u00e1-la, \u00e9 essencial considerar:","difficulty":5,"correct_position":4,"options":["somente o pre\u00e7o dos materiais.","apenas o t\u00edtulo da obra.","a biografia do visitante, sem olhar para a obra.","a rela\u00e7\u00e3o entre materiais, espa\u00e7o e experi\u00eancia do p\u00fablico."],"explanation":"A instala\u00e7\u00e3o integra espa\u00e7o e participa\u00e7\u00e3o; esses elementos fazem parte da constru\u00e7\u00e3o de sentido."},{"topic_slug":"artes-movimentos-brasileiros","prompt":"O Barroco brasileiro \u00e9 frequentemente reconhecido pelo uso de:","difficulty":1,"correct_position":2,"options":["formas sempre minimalistas e sem ornamenta\u00e7\u00e3o.","contrastes, dramaticidade e intensa ornamenta\u00e7\u00e3o.","fotografia digital como t\u00e9cnica central.","rejei\u00e7\u00e3o de temas religiosos em todos os casos."],"explanation":"Dramaticidade e ornamenta\u00e7\u00e3o s\u00e3o marcas recorrentes do Barroco, embora as obras sejam diversas."},{"topic_slug":"artes-movimentos-brasileiros","prompt":"A Semana de Arte Moderna de 1922 buscou:","difficulty":2,"correct_position":1,"options":["renovar as linguagens art\u00edsticas e discutir refer\u00eancias brasileiras.","retomar exclusivamente o padr\u00e3o barroco.","impedir a circula\u00e7\u00e3o de obras estrangeiras.","substituir as artes visuais pela arquitetura."],"explanation":"Os modernistas propuseram experimenta\u00e7\u00e3o e debate sobre a produ\u00e7\u00e3o cultural brasileira."},{"topic_slug":"artes-movimentos-brasileiros","prompt":"Uma obra modernista brasileira combina cores vivas e cenas cotidianas sem imitar fielmente a perspectiva acad\u00eamica. Isso pode revelar:","difficulty":3,"correct_position":4,"options":["falta de qualquer escolha est\u00e9tica.","uma regra universal de representa\u00e7\u00e3o realista.","a busca de linguagem pr\u00f3pria e experimenta\u00e7\u00e3o formal.","a obriga\u00e7\u00e3o de copiar modelos europeus."],"explanation":"A deforma\u00e7\u00e3o ou simplifica\u00e7\u00e3o pode ser uma escolha expressiva ligada \u00e0 renova\u00e7\u00e3o da linguagem."},{"topic_slug":"artes-movimentos-brasileiros","prompt":"O trabalho de artistas ind\u00edgenas contempor\u00e2neos deve ser compreendido como:","difficulty":4,"correct_position":3,"options":["uma tradi\u00e7\u00e3o parada no passado.","um conjunto de objetos sem autoria.","produ\u00e7\u00e3o atual e diversa, ligada a comunidades, trajet\u00f3rias e debates contempor\u00e2neos.","uma c\u00f3pia obrigat\u00f3ria da arte colonial."],"explanation":"Artistas ind\u00edgenas atuam no presente e expressam experi\u00eancias e propostas variadas."},{"topic_slug":"artes-movimentos-brasileiros","prompt":"Ao estudar influ\u00eancias africanas na arte brasileira, \u00e9 mais adequado:","difficulty":5,"correct_position":2,"options":["tratar culturas africanas como uma tradi\u00e7\u00e3o \u00fanica e imut\u00e1vel.","reconhecer matrizes diversas e seus processos hist\u00f3ricos, sem reduzir sua contribui\u00e7\u00e3o a um estere\u00f3tipo.","ignorar a di\u00e1spora e as trocas culturais.","limitar a an\u00e1lise a uma t\u00e9cnica art\u00edstica."],"explanation":"H\u00e1 muitas matrizes africanas e formas de cria\u00e7\u00e3o; uma leitura hist\u00f3rica evita generaliza\u00e7\u00f5es."},{"topic_slug":"artes-patrimonio-cultura","prompt":"Um bem cultural imaterial pode ser:","difficulty":1,"correct_position":3,"options":["somente um edif\u00edcio de pedra.","apenas uma pintura em tela.","uma celebra\u00e7\u00e3o, um saber ou uma pr\u00e1tica transmitida por uma comunidade.","qualquer produto industrial novo."],"explanation":"Patrim\u00f4nio imaterial inclui pr\u00e1ticas, express\u00f5es, conhecimentos e celebra\u00e7\u00f5es."},{"topic_slug":"artes-patrimonio-cultura","prompt":"Preservar um pr\u00e9dio hist\u00f3rico envolve tamb\u00e9m:","difficulty":2,"correct_position":4,"options":["impedir que qualquer pessoa conhe\u00e7a sua hist\u00f3ria.","apagar marcas de diferentes per\u00edodos.","considerar apenas seu valor comercial.","manter elementos significativos e registrar os usos e as mem\u00f3rias ligados a ele."],"explanation":"A preserva\u00e7\u00e3o considera materialidade, hist\u00f3ria, usos e v\u00ednculos sociais."},{"topic_slug":"artes-patrimonio-cultura","prompt":"Uma comunidade solicita reconhecimento de uma festa local como patrim\u00f4nio. Uma etapa importante \u00e9:","difficulty":3,"correct_position":1,"options":["documentar a pr\u00e1tica com participa\u00e7\u00e3o de quem a mant\u00e9m.","substituir a festa por uma encena\u00e7\u00e3o tur\u00edstica.","definir a tradi\u00e7\u00e3o sem ouvir seus participantes.","proibir mudan\u00e7as feitas pela pr\u00f3pria comunidade."],"explanation":"O registro respons\u00e1vel inclui a participa\u00e7\u00e3o dos grupos que praticam e transmitem a celebra\u00e7\u00e3o."},{"topic_slug":"artes-patrimonio-cultura","prompt":"Um museu atualiza uma exposi\u00e7\u00e3o ap\u00f3s ouvir grupos antes representados de forma estereotipada. A mudan\u00e7a busca:","difficulty":4,"correct_position":2,"options":["eliminar a pesquisa hist\u00f3rica.","ampliar as perspectivas e revisar formas de representa\u00e7\u00e3o.","tornar todas as obras iguais.","substituir objetos por propaganda."],"explanation":"A revis\u00e3o pode incorporar novas vozes e oferecer contexto mais plural."},{"topic_slug":"artes-patrimonio-cultura","prompt":"Uma pr\u00e1tica cultural muda ao longo do tempo, mas continua sendo reconhecida por seus praticantes. Isso indica que patrim\u00f4nio cultural:","difficulty":5,"correct_position":3,"options":["perde seu valor ao mudar.","deve ser congelado exatamente como surgiu.","pode permanecer vivo por meio de transmiss\u00e3o e transforma\u00e7\u00e3o comunit\u00e1ria.","s\u00f3 existe quando n\u00e3o h\u00e1 participantes."],"explanation":"Pr\u00e1ticas vivas podem se transformar enquanto s\u00e3o recriadas e transmitidas por comunidades."},{"topic_slug":"educacao-fisica-fisiologia-exercicio","prompt":"Durante uma atividade f\u00edsica, a hidrata\u00e7\u00e3o adequada ajuda principalmente a:","difficulty":1,"correct_position":2,"options":["substituir todas as refei\u00e7\u00f5es.","repor l\u00edquidos e apoiar o funcionamento do organismo.","impedir a necessidade de pausas.","garantir desempenho id\u00eantico para todos."],"explanation":"A hidrata\u00e7\u00e3o contribui para repor l\u00edquidos; necessidades variam com a atividade e a pessoa."},{"topic_slug":"educacao-fisica-fisiologia-exercicio","prompt":"A frequ\u00eancia card\u00edaca tende a aumentar durante exerc\u00edcio aer\u00f3bico porque o corpo precisa:","difficulty":2,"correct_position":4,"options":["reduzir o fluxo de sangue aos m\u00fasculos.","parar a respira\u00e7\u00e3o celular.","diminuir a temperatura a zero.","transportar mais oxig\u00eanio e nutrientes aos tecidos ativos."],"explanation":"O cora\u00e7\u00e3o aumenta o d\u00e9bito para atender \u00e0 maior demanda dos tecidos em atividade."},{"topic_slug":"educacao-fisica-fisiologia-exercicio","prompt":"Uma pessoa retoma os treinos ap\u00f3s longo per\u00edodo parada. A conduta mais prudente \u00e9:","difficulty":3,"correct_position":1,"options":["aumentar a carga gradualmente e observar a resposta do corpo.","come\u00e7ar com esfor\u00e7o m\u00e1ximo todos os dias.","ignorar dores persistentes.","usar a mesma rotina de atletas experientes."],"explanation":"A progress\u00e3o gradual reduz sobrecargas e permite adapta\u00e7\u00e3o."},{"topic_slug":"educacao-fisica-fisiologia-exercicio","prompt":"Por que o descanso entre sess\u00f5es intensas pode contribuir para a evolu\u00e7\u00e3o f\u00edsica?","difficulty":4,"correct_position":3,"options":["porque torna desnecess\u00e1ria qualquer atividade futura.","porque elimina a necessidade de alimenta\u00e7\u00e3o.","porque permite recupera\u00e7\u00e3o e adapta\u00e7\u00e3o do organismo ao esfor\u00e7o.","porque garante que n\u00e3o ocorrer\u00e3o les\u00f5es."],"explanation":"A recupera\u00e7\u00e3o faz parte do treinamento, embora n\u00e3o garanta aus\u00eancia total de les\u00f5es."},{"topic_slug":"educacao-fisica-fisiologia-exercicio","prompt":"Duas pessoas fazem a mesma atividade, mas percebem esfor\u00e7os diferentes. A explica\u00e7\u00e3o mais adequada \u00e9:","difficulty":5,"correct_position":2,"options":["o esfor\u00e7o \u00e9 sempre igual quando a dura\u00e7\u00e3o \u00e9 igual.","condicionamento, sa\u00fade, sono e intensidade percebida variam entre indiv\u00edduos.","uma delas necessariamente est\u00e1 executando o movimento errado.","a frequ\u00eancia card\u00edaca n\u00e3o muda com exerc\u00edcios."],"explanation":"A resposta ao exerc\u00edcio depende de fatores individuais e do contexto."},{"topic_slug":"educacao-fisica-danca-lutas","prompt":"Em uma dan\u00e7a coletiva, acompanhar o ritmo envolve principalmente:","difficulty":1,"correct_position":4,"options":["evitar qualquer rela\u00e7\u00e3o com a m\u00fasica.","repetir movimentos sem perceber o tempo.","competir para definir quem est\u00e1 certo.","coordenar movimentos com pulsa\u00e7\u00e3o, pausas e outros participantes."],"explanation":"Dan\u00e7ar envolve perceber ritmo e coordenar a\u00e7\u00f5es no tempo e no espa\u00e7o."},{"topic_slug":"educacao-fisica-danca-lutas","prompt":"Em uma luta praticada com regras e orienta\u00e7\u00e3o, o respeito ao parceiro inclui:","difficulty":2,"correct_position":1,"options":["controlar a for\u00e7a e interromper a a\u00e7\u00e3o quando solicitado.","continuar o golpe ap\u00f3s o sinal de parada.","ignorar os limites combinados.","transformar todo treino em confronto sem regras."],"explanation":"Seguran\u00e7a e respeito \u00e0s regras s\u00e3o centrais nas pr\u00e1ticas de luta."},{"topic_slug":"educacao-fisica-danca-lutas","prompt":"Uma roda de capoeira re\u00fane m\u00fasica, jogo e movimentos corporais. Essa pr\u00e1tica pode ser entendida como:","difficulty":3,"correct_position":3,"options":["somente uma sequ\u00eancia de exerc\u00edcios individuais.","um esporte sem dimens\u00e3o hist\u00f3rica.","uma manifesta\u00e7\u00e3o cultural que articula jogo, m\u00fasica e hist\u00f3ria.","uma dan\u00e7a sem intera\u00e7\u00e3o entre participantes."],"explanation":"A capoeira combina dimens\u00f5es corporais, musicais e hist\u00f3ricas."},{"topic_slug":"educacao-fisica-danca-lutas","prompt":"Ao ensinar uma dan\u00e7a de outra comunidade, uma escola deve:","difficulty":4,"correct_position":2,"options":["apresent\u00e1-la como curiosidade sem contexto.","pesquisar sua origem, reconhecer seus praticantes e evitar caricaturas.","retirar qualquer informa\u00e7\u00e3o cultural.","afirmar que a mesma dan\u00e7a significa o mesmo para todos."],"explanation":"Contextualiza\u00e7\u00e3o e respeito reduzem estere\u00f3tipos e reconhecem a autoria cultural."},{"topic_slug":"educacao-fisica-danca-lutas","prompt":"Uma adapta\u00e7\u00e3o em uma pr\u00e1tica corporal permite que participantes com diferentes mobilidades atuem juntos. O objetivo principal \u00e9:","difficulty":5,"correct_position":4,"options":["diminuir o valor da pr\u00e1tica.","separar participantes por capacidade.","eliminar desafios e regras em qualquer situa\u00e7\u00e3o.","ampliar acesso e participa\u00e7\u00e3o preservando o sentido da atividade."],"explanation":"Adapta\u00e7\u00f5es podem promover participa\u00e7\u00e3o sem apagar a proposta da pr\u00e1tica."},{"topic_slug":"educacao-fisica-inclusao-esporte","prompt":"Em uma partida, \u00e1rbitros aplicam as regras para:","difficulty":1,"correct_position":3,"options":["favorecer sempre a equipe mais popular.","mudar o resultado por prefer\u00eancia pessoal.","organizar o jogo e buscar condi\u00e7\u00f5es justas de participa\u00e7\u00e3o.","impedir que os jogadores tomem decis\u00f5es."],"explanation":"As regras estruturam a pr\u00e1tica e devem ser aplicadas com imparcialidade."},{"topic_slug":"educacao-fisica-inclusao-esporte","prompt":"Uma equipe combina passes e posi\u00e7\u00f5es antes do jogo. Essa organiza\u00e7\u00e3o favorece:","difficulty":2,"correct_position":1,"options":["coopera\u00e7\u00e3o e estrat\u00e9gia coletiva.","a elimina\u00e7\u00e3o da comunica\u00e7\u00e3o.","o desempenho isolado de todos.","a suspens\u00e3o das regras."],"explanation":"Planejar a\u00e7\u00f5es e comunicar-se pode ajudar a equipe a cooperar."},{"topic_slug":"educacao-fisica-inclusao-esporte","prompt":"Para incluir um participante com baixa vis\u00e3o em uma atividade, pode-se:","difficulty":3,"correct_position":4,"options":["impedir sua participa\u00e7\u00e3o para evitar mudan\u00e7as.","manter todas as condi\u00e7\u00f5es sem avaliar barreiras.","permitir que apenas observe.","usar sinal sonoro ou bola adaptada, combinando regras com o grupo."],"explanation":"Recursos e regras ajustados podem reduzir barreiras e ampliar participa\u00e7\u00e3o."},{"topic_slug":"educacao-fisica-inclusao-esporte","prompt":"Uma competi\u00e7\u00e3o escolar valoriza apenas quem vence e ridiculariza erros. Uma mudan\u00e7a educativa seria:","difficulty":4,"correct_position":2,"options":["retirar toda regra e objetivo.","avaliar tamb\u00e9m coopera\u00e7\u00e3o, esfor\u00e7o e respeito, al\u00e9m do resultado.","premiar sempre a equipe mais forte.","impedir iniciantes de participar."],"explanation":"A avalia\u00e7\u00e3o pode reconhecer aprendizagem e atitudes, n\u00e3o apenas vit\u00f3ria."},{"topic_slug":"educacao-fisica-inclusao-esporte","prompt":"Em um esporte, uma regra \u00e9 adaptada para uma turma iniciante. Para manter o car\u00e1ter educativo, a adapta\u00e7\u00e3o deve:","difficulty":5,"correct_position":3,"options":["favorecer secretamente uma equipe.","eliminar a participa\u00e7\u00e3o de quem aprende mais r\u00e1pido.","preservar seguran\u00e7a e oportunidade de participa\u00e7\u00e3o, explicando o objetivo da mudan\u00e7a.","ser escondida dos participantes."],"explanation":"Adapta\u00e7\u00f5es claras podem equilibrar o desafio e apoiar aprendizagem e seguran\u00e7a."},{"topic_slug":"redacao-estrutura-dissertativa","prompt":"Em um texto dissertativo-argumentativo, a introdu\u00e7\u00e3o costuma apresentar:","difficulty":1,"correct_position":2,"options":["apenas a lista de fontes.","o tema e uma tese que orienta a discuss\u00e3o.","a conclus\u00e3o antes dos argumentos.","uma sequ\u00eancia de instru\u00e7\u00f5es."],"explanation":"A introdu\u00e7\u00e3o situa o tema e apresenta o ponto de vista a ser defendido."},{"topic_slug":"redacao-estrutura-dissertativa","prompt":"Um par\u00e1grafo de desenvolvimento fica mais consistente quando:","difficulty":2,"correct_position":4,"options":["repete a tese sem explicar nada.","inclui exemplos sem rela\u00e7\u00e3o com o tema.","apresenta frases desconectadas.","apresenta uma ideia, sustenta-a com raz\u00f5es e explica sua rela\u00e7\u00e3o com a tese."],"explanation":"Argumentos precisam ser desenvolvidos e ligados ao ponto de vista central."},{"topic_slug":"redacao-estrutura-dissertativa","prompt":"Uma conclus\u00e3o retoma a tese e sintetiza os argumentos sem introduzir um tema novo. Essa escolha ajuda a:","difficulty":3,"correct_position":1,"options":["dar fechamento coerente ao texto.","apagar a fun\u00e7\u00e3o do desenvolvimento.","substituir a introdu\u00e7\u00e3o por uma pergunta.","transformar a reda\u00e7\u00e3o em narrativa."],"explanation":"Retomar a linha argumentativa d\u00e1 unidade e fechamento ao texto."},{"topic_slug":"redacao-estrutura-dissertativa","prompt":"Um texto tem tese clara, mas cada par\u00e1grafo defende uma ideia incompat\u00edvel com ela. O principal problema \u00e9:","difficulty":4,"correct_position":3,"options":["excesso de pontua\u00e7\u00e3o.","falta de t\u00edtulo, necessariamente.","incoer\u00eancia entre tese e desenvolvimento.","aus\u00eancia de narrador."],"explanation":"Os argumentos devem sustentar a tese; contradi\u00e7\u00f5es n\u00e3o explicadas prejudicam a coer\u00eancia."},{"topic_slug":"redacao-estrutura-dissertativa","prompt":"Ao revisar uma reda\u00e7\u00e3o, a autora percebe que duas ideias importantes aparecem no mesmo par\u00e1grafo sem liga\u00e7\u00e3o expl\u00edcita. Uma boa revis\u00e3o \u00e9:","difficulty":5,"correct_position":2,"options":["apagar uma delas sem avaliar seu papel.","explicitar a rela\u00e7\u00e3o l\u00f3gica e organizar as ideias em uma sequ\u00eancia compreens\u00edvel.","acrescentar conectivos aleat\u00f3rios.","trocar todos os substantivos por pronomes."],"explanation":"A revis\u00e3o deve tornar expl\u00edcita a rela\u00e7\u00e3o entre ideias e melhorar a progress\u00e3o argumentativa."},{"topic_slug":"redacao-repertorio-evidencias","prompt":"Em uma reda\u00e7\u00e3o, um dado estat\u00edstico \u00e9 mais \u00fatil quando:","difficulty":1,"correct_position":4,"options":["aparece sem fonte ou rela\u00e7\u00e3o com o tema.","substitui completamente a tese.","\u00e9 usado apenas por ser um n\u00famero grande.","\u00e9 explicado e relacionado ao argumento que pretende sustentar."],"explanation":"Dados precisam ser contextualizados e conectados ao racioc\u00ednio."},{"topic_slug":"redacao-repertorio-evidencias","prompt":"Uma cita\u00e7\u00e3o de especialista fortalece um argumento quando:","difficulty":2,"correct_position":1,"options":["\u00e9 pertinente ao tema e sua ideia \u00e9 explicada no texto.","o nome da pessoa \u00e9 conhecido, mesmo sem rela\u00e7\u00e3o com o assunto.","ocupa o lugar de toda an\u00e1lise.","\u00e9 apresentada sem fonte e sem contexto."],"explanation":"A autoridade s\u00f3 contribui quando a ideia citada \u00e9 relevante e interpretada."},{"topic_slug":"redacao-repertorio-evidencias","prompt":"Um estudante usa um exemplo pessoal para defender uma afirma\u00e7\u00e3o sobre toda a popula\u00e7\u00e3o. A limita\u00e7\u00e3o \u00e9 que:","difficulty":3,"correct_position":3,"options":["experi\u00eancias pessoais nunca podem ilustrar um argumento.","o exemplo prova automaticamente a afirma\u00e7\u00e3o geral.","um caso isolado, sozinho, n\u00e3o demonstra que a afirma\u00e7\u00e3o vale para todos.","exemplos n\u00e3o podem aparecer em reda\u00e7\u00f5es."],"explanation":"Um exemplo pode ilustrar, mas n\u00e3o basta para generalizar sem evid\u00eancias adicionais."},{"topic_slug":"redacao-repertorio-evidencias","prompt":"Duas fontes apresentam n\u00fameros diferentes sobre o mesmo tema. Antes de us\u00e1-los, \u00e9 importante comparar:","difficulty":4,"correct_position":2,"options":["somente a cor dos gr\u00e1ficos.","per\u00edodo, popula\u00e7\u00e3o, m\u00e9todo e defini\u00e7\u00e3o usada em cada levantamento.","qual fonte confirma a opini\u00e3o do autor.","apenas o tamanho dos n\u00fameros."],"explanation":"Diferen\u00e7as metodol\u00f3gicas podem explicar resultados distintos."},{"topic_slug":"redacao-repertorio-evidencias","prompt":"Um par\u00e1grafo apresenta um estudo e depois explica como seus resultados sustentam a tese. Esse procedimento demonstra:","difficulty":5,"correct_position":4,"options":["cita\u00e7\u00e3o decorativa.","argumento circular.","opini\u00e3o sem evid\u00eancia.","uso cr\u00edtico de evid\u00eancia articulada ao racioc\u00ednio."],"explanation":"A evid\u00eancia se torna argumento quando \u00e9 interpretada e relacionada \u00e0 tese."},{"topic_slug":"redacao-coesao-progressao","prompt":"Qual express\u00e3o pode introduzir uma consequ\u00eancia?","difficulty":1,"correct_position":2,"options":["apesar de","portanto","por exemplo","enquanto"],"explanation":"\u201cPortanto\u201d pode indicar uma conclus\u00e3o ou consequ\u00eancia l\u00f3gica."},{"topic_slug":"redacao-coesao-progressao","prompt":"Um texto repete \u201co problema\u201d em quase todas as frases. Uma revis\u00e3o pode melhorar a coes\u00e3o ao:","difficulty":2,"correct_position":3,"options":["retirar todos os referentes do texto.","trocar cada repeti\u00e7\u00e3o por um termo aleat\u00f3rio.","usar retomadas claras e variadas, mantendo o referente identific\u00e1vel.","inserir conectivos sem verificar as rela\u00e7\u00f5es."],"explanation":"Retomadas variadas evitam repeti\u00e7\u00e3o, desde que o leitor saiba a que se referem."},{"topic_slug":"redacao-coesao-progressao","prompt":"Um argumento come\u00e7a com \u201cpor outro lado\u201d, mas apresenta uma consequ\u00eancia da frase anterior, sem contraste. O ajuste mais adequado \u00e9:","difficulty":3,"correct_position":1,"options":["escolher um conectivo que exprima consequ\u00eancia, como \u201cpor isso\u201d.","manter o conectivo, pois todos t\u00eam o mesmo sentido.","retirar o argumento inteiro.","substituir por uma pergunta sem rela\u00e7\u00e3o."],"explanation":"O conectivo deve corresponder \u00e0 rela\u00e7\u00e3o l\u00f3gica entre as ideias."},{"topic_slug":"redacao-coesao-progressao","prompt":"Para que um texto progrida, cada par\u00e1grafo deve:","difficulty":4,"correct_position":4,"options":["repetir exatamente o anterior.","abandonar o tema central.","apresentar somente uma cita\u00e7\u00e3o.","acrescentar uma etapa relevante ao racioc\u00ednio, ligada ao que veio antes."],"explanation":"Progress\u00e3o articula continuidade tem\u00e1tica e avan\u00e7o da argumenta\u00e7\u00e3o."},{"topic_slug":"redacao-coesao-progressao","prompt":"Um pronome em \u201cIsso exige pol\u00edticas p\u00fablicas\u201d n\u00e3o tem antecedente claro. A revis\u00e3o mais eficaz \u00e9:","difficulty":5,"correct_position":2,"options":["remover toda a frase seguinte.","nomear a ideia retomada, por exemplo \u201cA redu\u00e7\u00e3o do desperd\u00edcio exige\u2026\u201d.","adicionar mais pronomes \u00e0 frase.","mudar o assunto para outro tema."],"explanation":"Tornar expl\u00edcito o referente evita ambiguidade e fortalece a liga\u00e7\u00e3o entre frases."},{"topic_slug":"matematica-funcoes-graficos","prompt":"Uma corrida de t\u00e1xi cobra R$ 6 de bandeirada mais R$ 2 por quil\u00f4metro. Qual express\u00e3o representa o pre\u00e7o P para x quil\u00f4metros?","difficulty":1,"correct_position":3,"options":["P=6x+2","P=2x\u22126","P=2x+6","P=8x"],"explanation":"A parte fixa \u00e9 6 e a parte vari\u00e1vel \u00e9 2 por quil\u00f4metro: P=2x+6."},{"topic_slug":"matematica-funcoes-graficos","prompt":"Na fun\u00e7\u00e3o f(x)=3x\u22124, qual \u00e9 o valor de f(5)?","difficulty":2,"correct_position":1,"options":["11","15","19","\u22121"],"explanation":"Substituindo x por 5: f(5)=3\u00b75\u22124=11."},{"topic_slug":"matematica-funcoes-graficos","prompt":"Uma reta passa pelos pontos (0, 2) e (4, 10). Qual \u00e9 sua taxa de varia\u00e7\u00e3o?","difficulty":3,"correct_position":1,"options":["2","4","8","12"],"explanation":"A inclina\u00e7\u00e3o \u00e9 (10\u22122)/(4\u22120)=2 unidades de y por unidade de x."},{"topic_slug":"matematica-funcoes-graficos","prompt":"Uma loja representa o saldo por S(n)=120\u221215n, em que n \u00e9 o n\u00famero de parcelas pagas. Depois de quantas parcelas o saldo chega a zero?","difficulty":4,"correct_position":2,"options":["6","8","9","15"],"explanation":"Resolvendo 120\u221215n=0, obtemos n=8."},{"topic_slug":"matematica-funcoes-graficos","prompt":"A altura de uma bola \u00e9 h(t)=\u22125t\u00b2+20t, em metros, ap\u00f3s t segundos. Em que instante ela volta ao solo?","difficulty":5,"correct_position":3,"options":["1 s","2 s","4 s","5 s"],"explanation":"Fatorando h(t)=\u22125t(t\u22124), as ra\u00edzes s\u00e3o 0 e 4; depois do lan\u00e7amento, ela toca o solo em 4 s."},{"topic_slug":"matematica-geometria-espacial","prompt":"Um cubo tem aresta de 3 cm. Qual \u00e9 seu volume?","difficulty":1,"correct_position":2,"options":["9 cm\u00b3","27 cm\u00b3","18 cm\u00b3","36 cm\u00b3"],"explanation":"O volume do cubo \u00e9 a\u00b3: 3\u00b3=27 cm\u00b3."},{"topic_slug":"matematica-geometria-espacial","prompt":"Uma caixa retangular mede 2 m por 3 m por 4 m. Qual \u00e9 seu volume?","difficulty":2,"correct_position":4,"options":["9 m\u00b3","12 m\u00b3","18 m\u00b3","24 m\u00b3"],"explanation":"Multiplicando comprimento, largura e altura: 2\u00b73\u00b74=24 m\u00b3."},{"topic_slug":"matematica-geometria-espacial","prompt":"Um cilindro tem raio 2 cm e altura 5 cm. Seu volume, em fun\u00e7\u00e3o de \u03c0, \u00e9:","difficulty":3,"correct_position":1,"options":["20\u03c0 cm\u00b3","10\u03c0 cm\u00b3","25\u03c0 cm\u00b3","40\u03c0 cm\u00b3"],"explanation":"V=\u03c0r\u00b2h=\u03c0\u00b72\u00b2\u00b75=20\u03c0 cm\u00b3."},{"topic_slug":"matematica-geometria-espacial","prompt":"Uma embalagem c\u00fabica tem volume de 64 cm\u00b3. Qual \u00e9 a \u00e1rea total de suas seis faces?","difficulty":4,"correct_position":3,"options":["16 cm\u00b2","64 cm\u00b2","96 cm\u00b2","128 cm\u00b2"],"explanation":"A aresta mede 4 cm; a \u00e1rea total \u00e9 6\u00b74\u00b2=96 cm\u00b2."},{"topic_slug":"matematica-geometria-espacial","prompt":"Um tanque em forma de prisma tem base retangular de 1,5 m por 2 m e altura de 1 m. Ele ser\u00e1 preenchido a 80% da capacidade. Quantos litros ser\u00e3o usados?","difficulty":5,"correct_position":2,"options":["1.200 L","2.400 L","3.000 L","4.000 L"],"explanation":"A capacidade \u00e9 1,5\u00b72\u00b71=3 m\u00b3=3.000 L; 80% corresponde a 2.400 L."},{"topic_slug":"matematica-estatistica-probabilidade","prompt":"As notas 6, 8 e 10 t\u00eam m\u00e9dia aritm\u00e9tica igual a:","difficulty":1,"correct_position":4,"options":["6","7","9","8"],"explanation":"A m\u00e9dia \u00e9 (6+8+10)/3=8."},{"topic_slug":"matematica-estatistica-probabilidade","prompt":"No conjunto 2, 4, 4, 7, 9, a mediana \u00e9:","difficulty":2,"correct_position":1,"options":["4","5","5,2","7"],"explanation":"O valor central, ap\u00f3s ordenar os dados, \u00e9 4."},{"topic_slug":"matematica-estatistica-probabilidade","prompt":"Uma caixa tem 3 bolas azuis e 2 vermelhas. Qual \u00e9 a probabilidade de retirar uma bola vermelha em uma tentativa?","difficulty":3,"correct_position":3,"options":["2/3","3/5","2/5","1/5"],"explanation":"H\u00e1 2 casos favor\u00e1veis em 5 resultados equiprov\u00e1veis: 2/5."},{"topic_slug":"matematica-estatistica-probabilidade","prompt":"Em uma turma, 12 estudantes usam \u00f4nibus, 8 usam bicicleta e 5 v\u00e3o a p\u00e9. Escolhido um estudante ao acaso, qual a probabilidade de ele usar bicicleta?","difficulty":4,"correct_position":2,"options":["8/12","8/25","5/25","12/25"],"explanation":"S\u00e3o 25 estudantes no total e 8 usam bicicleta, ent\u00e3o a probabilidade \u00e9 8/25."},{"topic_slug":"matematica-estatistica-probabilidade","prompt":"Um dado comum \u00e9 lan\u00e7ado duas vezes. Qual \u00e9 a probabilidade de sair 6 nas duas jogadas?","difficulty":5,"correct_position":4,"options":["1/6","1/12","1/18","1/36"],"explanation":"Os lan\u00e7amentos s\u00e3o independentes: (1/6)\u00b7(1/6)=1/36."},{"topic_slug":"biologia-fisiologia-humana","prompt":"Qual \u00e9 a principal fun\u00e7\u00e3o das hem\u00e1cias no transporte sangu\u00edneo?","difficulty":1,"correct_position":1,"options":["transportar oxig\u00eanio com aux\u00edlio da hemoglobina.","produzir bile.","filtrar urina nos rins.","realizar a digest\u00e3o de prote\u00ednas."],"explanation":"A hemoglobina das hem\u00e1cias se liga ao oxig\u00eanio e participa de seu transporte."},{"topic_slug":"biologia-fisiologia-humana","prompt":"Durante a inspira\u00e7\u00e3o, o diafragma normalmente:","difficulty":2,"correct_position":3,"options":["relaxa e sobe, reduzindo o volume tor\u00e1cico.","fecha a traqueia para reter ar.","contrai e desce, aumentando o volume tor\u00e1cico.","interrompe a circula\u00e7\u00e3o pulmonar."],"explanation":"A contra\u00e7\u00e3o do diafragma amplia a cavidade tor\u00e1cica e favorece a entrada de ar."},{"topic_slug":"biologia-fisiologia-humana","prompt":"Ap\u00f3s uma refei\u00e7\u00e3o, o n\u00edvel de glicose no sangue aumenta. Qual horm\u00f4nio ajuda a favorecer sua entrada em muitas c\u00e9lulas?","difficulty":3,"correct_position":2,"options":["adrenalina","insulina","melatonina","tiroxina"],"explanation":"A insulina contribui para a capta\u00e7\u00e3o de glicose e a regula\u00e7\u00e3o da glicemia."},{"topic_slug":"biologia-fisiologia-humana","prompt":"Os rins ajudam a manter o equil\u00edbrio interno do corpo porque:","difficulty":4,"correct_position":4,"options":["produzem oxig\u00eanio para as c\u00e9lulas.","controlam diretamente os movimentos volunt\u00e1rios.","transformam nutrientes em luz.","filtram o sangue e regulam \u00e1gua e sais na forma\u00e7\u00e3o da urina."],"explanation":"A filtra\u00e7\u00e3o renal e a regula\u00e7\u00e3o de \u00e1gua e \u00edons ajudam na homeostase."},{"topic_slug":"biologia-fisiologia-humana","prompt":"Durante exerc\u00edcio prolongado em ambiente quente, o suor aumenta. Qual combina\u00e7\u00e3o explica melhor seu papel e um cuidado associado?","difficulty":5,"correct_position":1,"options":["a evapora\u00e7\u00e3o pode ajudar a dissipar calor, enquanto a perda de \u00e1gua exige reposi\u00e7\u00e3o adequada.","o suor reduz a temperatura por congelamento e dispensa \u00e1gua.","o suor interrompe a circula\u00e7\u00e3o e impede a perda de calor.","a produ\u00e7\u00e3o de suor substitui os sais e nutrientes da alimenta\u00e7\u00e3o."],"explanation":"A evapora\u00e7\u00e3o do suor retira calor, mas a perda de l\u00edquidos deve ser considerada."},{"topic_slug":"biologia-microbiologia-imunizacao","prompt":"Antibi\u00f3ticos atuam principalmente contra:","difficulty":1,"correct_position":4,"options":["v\u00edrus como o da gripe.","qualquer agente infeccioso, sem distin\u00e7\u00e3o.","c\u00e9lulas humanas infectadas apenas.","bact\u00e9rias suscet\u00edveis ao medicamento."],"explanation":"Antibi\u00f3ticos t\u00eam alvos bacterianos; n\u00e3o tratam diretamente infec\u00e7\u00f5es virais."},{"topic_slug":"biologia-microbiologia-imunizacao","prompt":"Vacinas ajudam a prevenir algumas doen\u00e7as porque:","difficulty":2,"correct_position":2,"options":["eliminam todos os microrganismos do ambiente.","estimulam o sistema imune a reconhecer componentes do agente e a responder melhor depois.","substituem permanentemente todas as defesas do corpo.","agem como antibi\u00f3ticos contra qualquer v\u00edrus."],"explanation":"A vacina\u00e7\u00e3o prepara respostas imunes espec\u00edficas e pode reduzir o risco de doen\u00e7a ou gravidade."},{"topic_slug":"biologia-microbiologia-imunizacao","prompt":"Uma infec\u00e7\u00e3o viral n\u00e3o melhora com antibi\u00f3tico porque:","difficulty":3,"correct_position":1,"options":["v\u00edrus n\u00e3o possuem os mesmos alvos celulares das bact\u00e9rias usados por esses medicamentos.","antibi\u00f3ticos s\u00f3 funcionam em temperaturas baixas.","v\u00edrus s\u00e3o sempre maiores que bact\u00e9rias.","antibi\u00f3ticos impedem a produ\u00e7\u00e3o de anticorpos."],"explanation":"Muitos antibi\u00f3ticos interferem em estruturas ou processos bacterianos que v\u00edrus n\u00e3o t\u00eam."},{"topic_slug":"biologia-microbiologia-imunizacao","prompt":"O uso de antibi\u00f3ticos sem necessidade pode favorecer resist\u00eancia porque:","difficulty":4,"correct_position":3,"options":["cada bact\u00e9ria decide adaptar-se de prop\u00f3sito.","o medicamento transforma todos os v\u00edrus em bact\u00e9rias.","bact\u00e9rias resistentes podem sobreviver e se multiplicar quando as suscet\u00edveis s\u00e3o eliminadas.","o corpo humano passa a fabricar antibi\u00f3ticos."],"explanation":"A sele\u00e7\u00e3o favorece microrganismos resistentes que j\u00e1 estavam presentes ou surgem por varia\u00e7\u00e3o."},{"topic_slug":"biologia-microbiologia-imunizacao","prompt":"Em uma comunidade, a cobertura vacinal cai e aumentam os casos de uma doen\u00e7a transmiss\u00edvel. Uma consequ\u00eancia poss\u00edvel \u00e9:","difficulty":5,"correct_position":2,"options":["o agente deixar de circular imediatamente.","mais pessoas suscet\u00edveis, o que pode facilitar cadeias de transmiss\u00e3o.","a imunidade individual desaparecer em todos no mesmo dia.","a doen\u00e7a passar a ser causada por bact\u00e9rias."],"explanation":"Com menos pessoas protegidas, aumentam oportunidades de transmiss\u00e3o e surtos."},{"topic_slug":"biologia-biotecnologia-bioetica","prompt":"A t\u00e9cnica de PCR \u00e9 usada em laborat\u00f3rio principalmente para:","difficulty":1,"correct_position":3,"options":["medir a press\u00e3o arterial.","produzir prote\u00ednas sem material gen\u00e9tico.","amplificar trechos espec\u00edficos de DNA.","transformar bact\u00e9rias em v\u00edrus."],"explanation":"A PCR produz muitas c\u00f3pias de uma regi\u00e3o-alvo de DNA."},{"topic_slug":"biologia-biotecnologia-bioetica","prompt":"Um organismo transg\u00eanico \u00e9 aquele que:","difficulty":2,"correct_position":1,"options":["recebeu material gen\u00e9tico introduzido por t\u00e9cnicas de engenharia gen\u00e9tica.","vive em ambiente urbano.","se reproduz sem qualquer gene.","\u00e9 necessariamente uma esp\u00e9cie extinta."],"explanation":"Transgenia envolve introdu\u00e7\u00e3o de material gen\u00e9tico por t\u00e9cnicas de engenharia."},{"topic_slug":"biologia-biotecnologia-bioetica","prompt":"Antes de aprovar um teste gen\u00e9tico para uso cl\u00ednico, \u00e9 importante avaliar:","difficulty":3,"correct_position":4,"options":["apenas o custo do aparelho.","somente a apar\u00eancia do resultado.","se o exame substitui toda conversa com o paciente.","validade, riscos, privacidade e consentimento informado."],"explanation":"Uma avalia\u00e7\u00e3o respons\u00e1vel inclui evid\u00eancia cl\u00ednica e implica\u00e7\u00f5es \u00e9ticas e de privacidade."},{"topic_slug":"biologia-biotecnologia-bioetica","prompt":"Uma planta resistente a determinada praga pode reduzir algumas perdas agr\u00edcolas. Para avaliar o impacto da tecnologia, tamb\u00e9m \u00e9 necess\u00e1rio:","difficulty":4,"correct_position":2,"options":["presumir que todo efeito ambiental ser\u00e1 positivo.","analisar evid\u00eancias sobre ecossistemas, manejo e condi\u00e7\u00f5es locais.","ignorar o uso de outras pr\u00e1ticas agr\u00edcolas.","concluir que a tecnologia n\u00e3o tem qualquer benef\u00edcio."],"explanation":"Os resultados dependem do contexto; benef\u00edcios e riscos devem ser avaliados com dados."},{"topic_slug":"biologia-biotecnologia-bioetica","prompt":"Um banco de dados gen\u00e9ticos \u00e9 proposto para pesquisa. Qual medida \u00e9tica \u00e9 mais importante?","difficulty":5,"correct_position":3,"options":["publicar nomes e resultados para garantir transpar\u00eancia total.","dispensar consentimento em qualquer situa\u00e7\u00e3o.","proteger dados identific\u00e1veis e definir finalidade, acesso e consentimento.","permitir acesso irrestrito a qualquer empresa."],"explanation":"Dados gen\u00e9ticos s\u00e3o sens\u00edveis; governan\u00e7a e consentimento reduzem riscos de uso indevido."},{"topic_slug":"fisica-hidrostatica-pressao","prompt":"Uma for\u00e7a de 20 N atua perpendicularmente sobre uma \u00e1rea de 2 m\u00b2. Qual \u00e9 a press\u00e3o m\u00e9dia?","difficulty":1,"correct_position":2,"options":["5 Pa","10 Pa","40 Pa","22 Pa"],"explanation":"Press\u00e3o \u00e9 for\u00e7a dividida pela \u00e1rea: 20/2=10 Pa."},{"topic_slug":"fisica-hidrostatica-pressao","prompt":"Mantida a mesma for\u00e7a, se a \u00e1rea de contato de um objeto diminui, a press\u00e3o:","difficulty":2,"correct_position":4,"options":["diminui na mesma propor\u00e7\u00e3o.","permanece sempre zero.","n\u00e3o depende da \u00e1rea.","aumenta."],"explanation":"Como P=F/A, reduzir a \u00e1rea aumenta a press\u00e3o para a mesma for\u00e7a."},{"topic_slug":"fisica-hidrostatica-pressao","prompt":"Em um l\u00edquido em repouso, a press\u00e3o tende a ser maior:","difficulty":3,"correct_position":1,"options":["em pontos mais profundos, se a densidade for a mesma.","na superf\u00edcie, sempre.","apenas perto das margens.","onde o recipiente \u00e9 mais largo, independentemente da profundidade."],"explanation":"A press\u00e3o hidrost\u00e1tica cresce com a profundidade: p=\u03c1gh."},{"topic_slug":"fisica-hidrostatica-pressao","prompt":"Dois pontos est\u00e3o \u00e0 mesma profundidade no mesmo l\u00edquido em repouso. Desprezando diferen\u00e7as locais, suas press\u00f5es hidrost\u00e1ticas s\u00e3o:","difficulty":4,"correct_position":3,"options":["maior no recipiente mais estreito.","maior no ponto mais distante da parede.","iguais, pois dependem da densidade e da profundidade.","iguais somente se os recipientes tiverem o mesmo formato."],"explanation":"A press\u00e3o hidrost\u00e1tica depende da densidade do l\u00edquido e da profundidade, n\u00e3o do formato do recipiente."},{"topic_slug":"fisica-hidrostatica-pressao","prompt":"Um objeto desloca 0,002 m\u00b3 de \u00e1gua. Usando densidade da \u00e1gua 1.000 kg/m\u00b3 e g\u224810 m/s\u00b2, qual \u00e9 o empuxo?","difficulty":5,"correct_position":1,"options":["20 N","2 N","200 N","0,2 N"],"explanation":"O empuxo \u00e9 o peso do l\u00edquido deslocado: \u03c1gV=1000\u00b710\u00b70,002=20 N."},{"topic_slug":"fisica-ondas-acustica","prompt":"Uma onda realiza 10 oscila\u00e7\u00f5es em 2 segundos. Qual \u00e9 sua frequ\u00eancia?","difficulty":1,"correct_position":2,"options":["2 Hz","5 Hz","10 Hz","20 Hz"],"explanation":"Frequ\u00eancia \u00e9 o n\u00famero de oscila\u00e7\u00f5es por segundo: 10/2=5 Hz."},{"topic_slug":"fisica-ondas-acustica","prompt":"Se a frequ\u00eancia de um som aumenta, sua percep\u00e7\u00e3o de altura tende a ficar:","difficulty":2,"correct_position":4,"options":["mais grave.","mais silenciosa necessariamente.","inalterada em qualquer situa\u00e7\u00e3o.","mais aguda."],"explanation":"A altura do som se relaciona \u00e0 frequ\u00eancia: frequ\u00eancias maiores s\u00e3o percebidas como sons mais agudos."},{"topic_slug":"fisica-ondas-acustica","prompt":"Uma onda tem velocidade de 12 m/s e frequ\u00eancia de 3 Hz. Qual \u00e9 seu comprimento de onda?","difficulty":3,"correct_position":2,"options":["36 m","4 m","9 m","0,25 m"],"explanation":"Usando v=\u03bbf, obtemos \u03bb=12/3=4 m."},{"topic_slug":"fisica-ondas-acustica","prompt":"Uma pessoa ouve o eco 0,4 s ap\u00f3s emitir um som. Se a velocidade do som \u00e9 340 m/s, a parede est\u00e1 aproximadamente a:","difficulty":4,"correct_position":1,"options":["68 m","136 m","170 m","340 m"],"explanation":"O som percorre ida e volta: dist\u00e2ncia at\u00e9 a parede=340\u00b70,4/2=68 m."},{"topic_slug":"fisica-ondas-acustica","prompt":"Em uma mesma corda tensionada, uma onda passa a oscilar com o dobro da frequ\u00eancia. Como sua velocidade se mant\u00e9m aproximadamente constante, o comprimento de onda:","difficulty":5,"correct_position":3,"options":["dobra.","quadruplica.","cai pela metade.","permanece igual."],"explanation":"Como v=\u03bbf e v \u00e9 constante, dobrar f reduz \u03bb \u00e0 metade."},{"topic_slug":"fisica-optica-espelhos-lentes","prompt":"Em um espelho plano, o \u00e2ngulo de reflex\u00e3o \u00e9:","difficulty":1,"correct_position":2,"options":["sempre o dobro do \u00e2ngulo de incid\u00eancia.","igual ao \u00e2ngulo de incid\u00eancia, medidos em rela\u00e7\u00e3o \u00e0 normal.","sempre 90 graus.","independente da dire\u00e7\u00e3o da luz."],"explanation":"A lei da reflex\u00e3o estabelece \u00e2ngulos de incid\u00eancia e reflex\u00e3o iguais."},{"topic_slug":"fisica-optica-espelhos-lentes","prompt":"Uma imagem em espelho plano \u00e9 normalmente:","difficulty":2,"correct_position":4,"options":["real, invertida verticalmente e menor.","real e ampliada.","projet\u00e1vel em uma tela.","virtual, direita e de tamanho igual ao objeto."],"explanation":"O espelho plano forma imagem virtual, direita e sim\u00e9trica, com o mesmo tamanho."},{"topic_slug":"fisica-optica-espelhos-lentes","prompt":"Ao passar do ar para a \u00e1gua, a luz muda de velocidade e pode mudar de dire\u00e7\u00e3o. Esse fen\u00f4meno \u00e9:","difficulty":3,"correct_position":1,"options":["refra\u00e7\u00e3o.","difra\u00e7\u00e3o sonora.","polariza\u00e7\u00e3o magn\u00e9tica.","combust\u00e3o."],"explanation":"A mudan\u00e7a de meio que altera a velocidade da luz pode causar refra\u00e7\u00e3o."},{"topic_slug":"fisica-optica-espelhos-lentes","prompt":"Uma lente convergente forma uma imagem real quando o objeto est\u00e1:","difficulty":4,"correct_position":3,"options":["entre a lente e o foco.","exatamente no centro da lente em qualquer condi\u00e7\u00e3o.","al\u00e9m da dist\u00e2ncia focal.","em qualquer posi\u00e7\u00e3o, inclusive sobre o foco."],"explanation":"Com o objeto al\u00e9m do foco, uma lente convergente pode formar imagem real no outro lado."},{"topic_slug":"fisica-optica-espelhos-lentes","prompt":"Ao observar uma colher parcialmente mergulhada em \u00e1gua, ela parece deslocada na superf\u00edcie. A explica\u00e7\u00e3o mais adequada \u00e9:","difficulty":5,"correct_position":2,"options":["a reflex\u00e3o total dentro do metal.","a refra\u00e7\u00e3o da luz ao passar entre \u00e1gua e ar.","a produ\u00e7\u00e3o de luz pela colher.","a absor\u00e7\u00e3o completa da luz pela \u00e1gua."],"explanation":"A luz muda de dire\u00e7\u00e3o na interface entre meios, alterando a posi\u00e7\u00e3o aparente."},{"topic_slug":"quimica-estequiometria-moles","prompt":"Na rea\u00e7\u00e3o 2 H\u2082 + O\u2082 \u2192 2 H\u2082O, quantas mol\u00e9culas de H\u2082 s\u00e3o necess\u00e1rias para cada mol\u00e9cula de O\u2082?","difficulty":1,"correct_position":4,"options":["1","3","4","2"],"explanation":"Os coeficientes da equa\u00e7\u00e3o indicam a propor\u00e7\u00e3o de 2 mol\u00e9culas de H\u2082 para 1 de O\u2082."},{"topic_slug":"quimica-estequiometria-moles","prompt":"Na rea\u00e7\u00e3o N\u2082 + 3 H\u2082 \u2192 2 NH\u2083, 1 mol de N\u2082 pode formar, teoricamente, quantos mols de NH\u2083 com H\u2082 em excesso?","difficulty":2,"correct_position":1,"options":["2 mol","1 mol","3 mol","6 mol"],"explanation":"A propor\u00e7\u00e3o estequiom\u00e9trica \u00e9 1 mol de N\u2082 para 2 mol de NH\u2083."},{"topic_slug":"quimica-estequiometria-moles","prompt":"Na rea\u00e7\u00e3o 2 Mg + O\u2082 \u2192 2 MgO, 4 mol de Mg reagem completamente com quantos mols de O\u2082?","difficulty":3,"correct_position":3,"options":["1 mol","4 mol","2 mol","8 mol"],"explanation":"Dois mols de Mg reagem com um mol de O\u2082; 4 mol de Mg consomem 2 mol de O\u2082."},{"topic_slug":"quimica-estequiometria-moles","prompt":"Uma rea\u00e7\u00e3o produz 8 g de produto, embora o rendimento te\u00f3rico fosse 10 g. Qual foi o rendimento percentual?","difficulty":4,"correct_position":2,"options":["20%","80%","100%","125%"],"explanation":"Rendimento percentual=(8/10)\u00b7100=80%."},{"topic_slug":"quimica-estequiometria-moles","prompt":"Na rea\u00e7\u00e3o 2 H\u2082 + O\u2082 \u2192 2 H\u2082O, misturam-se 5 mol de H\u2082 e 2 mol de O\u2082. Considerando rea\u00e7\u00e3o completa, qual \u00e9 o reagente limitante e quanto H\u2082 sobra?","difficulty":5,"correct_position":4,"options":["H\u2082; sobra 1 mol de O\u2082.","O\u2082; sobra 3 mol de H\u2082.","H\u2082; n\u00e3o sobra nenhum reagente.","O\u2082; sobra 1 mol de H\u2082."],"explanation":"2 mol de O\u2082 consomem 4 mol de H\u2082; o O\u2082 limita a rea\u00e7\u00e3o e sobra 1 mol de H\u2082."},{"topic_slug":"quimica-acidos-bases-ph","prompt":"Em solu\u00e7\u00f5es aquosas usuais, um pH menor que 7 indica car\u00e1ter:","difficulty":1,"correct_position":1,"options":["\u00e1cido.","neutro.","b\u00e1sico.","met\u00e1lico."],"explanation":"Na escala usual, valores menores que 7 indicam meio \u00e1cido."},{"topic_slug":"quimica-acidos-bases-ph","prompt":"Uma solu\u00e7\u00e3o tem pH 3 e outra pH 5. A primeira tem concentra\u00e7\u00e3o de \u00edons H\u207a aproximadamente:","difficulty":2,"correct_position":4,"options":["duas vezes maior.","duas vezes menor.","100 vezes menor.","100 vezes maior."],"explanation":"Cada unidade de pH representa fator 10; diferen\u00e7a de 2 unidades corresponde a fator 100."},{"topic_slug":"quimica-acidos-bases-ph","prompt":"Uma solu\u00e7\u00e3o \u00e1cida \u00e9 misturada a uma quantidade adequada de base e forma \u00e1gua e sal. Esse processo \u00e9 chamado:","difficulty":3,"correct_position":2,"options":["oxida\u00e7\u00e3o.","neutraliza\u00e7\u00e3o.","sublima\u00e7\u00e3o.","destila\u00e7\u00e3o."],"explanation":"Uma rea\u00e7\u00e3o entre \u00e1cido e base pode neutralizar parcialmente ou completamente suas propriedades."},{"topic_slug":"quimica-acidos-bases-ph","prompt":"Um indicador fica vermelho em meio \u00e1cido e azul em meio b\u00e1sico. Uma amostra o deixa azul. A conclus\u00e3o mais adequada \u00e9:","difficulty":4,"correct_position":3,"options":["a amostra \u00e9 necessariamente neutra.","a amostra n\u00e3o cont\u00e9m \u00e1gua.","o resultado indica meio b\u00e1sico dentro das condi\u00e7\u00f5es do indicador.","o indicador mede diretamente a massa da amostra."],"explanation":"A cor observada \u00e9 compat\u00edvel com meio b\u00e1sico segundo a caracter\u00edstica informada."},{"topic_slug":"quimica-acidos-bases-ph","prompt":"Uma amostra de pH 4 \u00e9 dilu\u00edda com \u00e1gua pura, sem rea\u00e7\u00e3o adicional. Em geral, seu pH tende a:","difficulty":5,"correct_position":1,"options":["aproximar-se de 7, embora permane\u00e7a dependente da concentra\u00e7\u00e3o final.","diminuir para 1 em qualquer volume.","permanecer sempre exatamente 4.","tornar-se maior que 14."],"explanation":"A dilui\u00e7\u00e3o reduz a concentra\u00e7\u00e3o de H\u207a e tende a aproximar o pH do neutro."},{"topic_slug":"quimica-eletroquimica-pilhas","prompt":"Em uma pilha funcionando espontaneamente, a energia qu\u00edmica \u00e9 convertida principalmente em:","difficulty":1,"correct_position":2,"options":["energia sonora.","energia el\u00e9trica.","energia nuclear.","energia gravitacional."],"explanation":"Uma pilha converte energia de uma rea\u00e7\u00e3o redox espont\u00e2nea em energia el\u00e9trica."},{"topic_slug":"quimica-eletroquimica-pilhas","prompt":"Oxida\u00e7\u00e3o corresponde \u00e0:","difficulty":2,"correct_position":4,"options":["ganho de pr\u00f3tons.","perda de n\u00eautrons.","forma\u00e7\u00e3o de \u00e1gua em qualquer rea\u00e7\u00e3o.","perda de el\u00e9trons."],"explanation":"Oxida\u00e7\u00e3o \u00e9 perda de el\u00e9trons; redu\u00e7\u00e3o \u00e9 ganho de el\u00e9trons."},{"topic_slug":"quimica-eletroquimica-pilhas","prompt":"Na corros\u00e3o do ferro, a presen\u00e7a de \u00e1gua e oxig\u00eanio geralmente:","difficulty":3,"correct_position":3,"options":["impede qualquer rea\u00e7\u00e3o na superf\u00edcie.","transforma ferro em pl\u00e1stico.","favorece processos de oxida\u00e7\u00e3o que formam produtos de corros\u00e3o.","reduz a massa de oxig\u00eanio do ambiente a zero."],"explanation":"\u00c1gua e oxig\u00eanio participam das rea\u00e7\u00f5es eletroqu\u00edmicas que corroem o ferro."},{"topic_slug":"quimica-eletroquimica-pilhas","prompt":"Um revestimento de zinco pode proteger o ferro mesmo se houver pequeno risco na superf\u00edcie porque o zinco:","difficulty":4,"correct_position":1,"options":["pode oxidar-se preferencialmente e atuar como metal de sacrif\u00edcio.","impede a exist\u00eancia de el\u00e9trons no metal.","transforma o ferro em isolante perfeito.","remove todo o oxig\u00eanio do ar."],"explanation":"O zinco tende a oxidar-se antes do ferro, oferecendo prote\u00e7\u00e3o sacrificial."},{"topic_slug":"quimica-eletroquimica-pilhas","prompt":"Em uma pilha, os el\u00e9trons fluem pelo circuito externo do \u00e2nodo para o c\u00e1todo. Isso \u00e9 compat\u00edvel com:","difficulty":5,"correct_position":4,"options":["redu\u00e7\u00e3o no \u00e2nodo e oxida\u00e7\u00e3o no c\u00e1todo.","ganho de el\u00e9trons no \u00e2nodo.","fluxo de el\u00e9trons pelo eletr\u00f3lito externo.","oxida\u00e7\u00e3o no \u00e2nodo e redu\u00e7\u00e3o no c\u00e1todo."],"explanation":"Na pilha, ocorre oxida\u00e7\u00e3o no \u00e2nodo e redu\u00e7\u00e3o no c\u00e1todo; os el\u00e9trons seguem externamente entre eles."},{"topic_slug":"historia-antiguidade-classica","prompt":"Na Gr\u00e9cia antiga, a p\u00f3lis era:","difficulty":1,"correct_position":3,"options":["um imp\u00e9rio governado por um fara\u00f3.","uma prov\u00edncia romana.","uma comunidade pol\u00edtica aut\u00f4noma, com institui\u00e7\u00f5es pr\u00f3prias.","um templo sem popula\u00e7\u00e3o civil."],"explanation":"A p\u00f3lis era uma cidade-Estado com organiza\u00e7\u00e3o pol\u00edtica e social pr\u00f3pria."},{"topic_slug":"historia-antiguidade-classica","prompt":"A democracia ateniense antiga permitia participa\u00e7\u00e3o pol\u00edtica direta principalmente a:","difficulty":2,"correct_position":1,"options":["homens adultos reconhecidos como cidad\u00e3os, excluindo v\u00e1rios grupos da popula\u00e7\u00e3o.","todas as pessoas que viviam na cidade, sem distin\u00e7\u00e3o.","apenas estrangeiros comerciantes.","mulheres e pessoas escravizadas em igualdade de condi\u00e7\u00f5es."],"explanation":"A cidadania ateniense era restrita; mulheres, estrangeiros e pessoas escravizadas eram exclu\u00eddos da participa\u00e7\u00e3o pol\u00edtica."},{"topic_slug":"historia-antiguidade-classica","prompt":"Na Rep\u00fablica Romana, magistraturas e Senado faziam parte de:","difficulty":3,"correct_position":4,"options":["um sistema em que o imperador era eleito por todos os habitantes.","uma organiza\u00e7\u00e3o pol\u00edtica sem conflitos sociais.","uma democracia universal com sufr\u00e1gio feminino.","institui\u00e7\u00f5es de governo controladas por grupos de cidad\u00e3os e elites."],"explanation":"A Rep\u00fablica combinou institui\u00e7\u00f5es pol\u00edticas e forte influ\u00eancia da aristocracia, sem participa\u00e7\u00e3o universal."},{"topic_slug":"historia-antiguidade-classica","prompt":"A expans\u00e3o romana pelo Mediterr\u00e2neo aumentou o territ\u00f3rio e tamb\u00e9m:","difficulty":4,"correct_position":2,"options":["eliminou imediatamente as diferen\u00e7as sociais.","ampliou a circula\u00e7\u00e3o de pessoas, riquezas e pessoas escravizadas.","acabou com o uso de ex\u00e9rcitos.","impediu trocas comerciais entre regi\u00f5es."],"explanation":"A expans\u00e3o integrou territ\u00f3rios e intensificou fluxos, conquistas e escraviza\u00e7\u00e3o."},{"topic_slug":"historia-antiguidade-classica","prompt":"Uma fonte antiga registra que apenas certos homens participavam da assembleia. Para interpretar essa informa\u00e7\u00e3o, o historiador deve:","difficulty":5,"correct_position":3,"options":["tom\u00e1-la como descri\u00e7\u00e3o de toda a popula\u00e7\u00e3o sem cr\u00edtica.","supor que todos os habitantes eram cidad\u00e3os.","considerar quem produziu a fonte, quem era cidad\u00e3o e quem foi exclu\u00eddo.","descartar a fonte porque ela n\u00e3o fala de todos."],"explanation":"A an\u00e1lise contextual identifica os limites da cidadania e da pr\u00f3pria fonte."},{"topic_slug":"historia-revolucoes-industriais","prompt":"A Primeira Revolu\u00e7\u00e3o Industrial come\u00e7ou na Inglaterra no s\u00e9culo XVIII e se destacou pelo uso crescente de:","difficulty":1,"correct_position":2,"options":["energia nuclear em f\u00e1bricas automatizadas.","m\u00e1quinas movidas a vapor e produ\u00e7\u00e3o fabril.","computadores pessoais.","pain\u00e9is solares em linhas robotizadas."],"explanation":"A m\u00e1quina a vapor e a mecaniza\u00e7\u00e3o fabril foram centrais na primeira industrializa\u00e7\u00e3o."},{"topic_slug":"historia-revolucoes-industriais","prompt":"A expans\u00e3o das f\u00e1bricas contribuiu para:","difficulty":2,"correct_position":4,"options":["o desaparecimento das cidades.","o fim imediato das desigualdades.","o retorno generalizado ao trabalho dom\u00e9stico artesanal.","urbaniza\u00e7\u00e3o e reorganiza\u00e7\u00e3o do trabalho em torno das f\u00e1bricas."],"explanation":"A industrializa\u00e7\u00e3o atraiu trabalhadores para centros urbanos e alterou rela\u00e7\u00f5es de trabalho."},{"topic_slug":"historia-revolucoes-industriais","prompt":"A substitui\u00e7\u00e3o de parte do trabalho artesanal por m\u00e1quinas alterou a produ\u00e7\u00e3o porque:","difficulty":3,"correct_position":1,"options":["aumentou a mecaniza\u00e7\u00e3o e concentrou trabalhadores em espa\u00e7os fabris.","eliminou todas as etapas de produ\u00e7\u00e3o.","impediu a fabrica\u00e7\u00e3o em grande escala.","fez desaparecer o com\u00e9rcio internacional."],"explanation":"A mecaniza\u00e7\u00e3o ampliou a produ\u00e7\u00e3o em s\u00e9rie e reorganizou o trabalho fabril."},{"topic_slug":"historia-revolucoes-industriais","prompt":"Uma ind\u00fastria busca mat\u00e9rias-primas e mercados em territ\u00f3rios distantes durante o s\u00e9culo XIX. Essa din\u00e2mica pode se relacionar:","difficulty":4,"correct_position":3,"options":["ao isolamento econ\u00f4mico completo.","\u00e0 elimina\u00e7\u00e3o dos imp\u00e9rios coloniais no per\u00edodo.","\u00e0 expans\u00e3o imperialista e \u00e0 integra\u00e7\u00e3o desigual de economias.","\u00e0 aus\u00eancia de industrializa\u00e7\u00e3o na Europa."],"explanation":"Industrializa\u00e7\u00e3o e imperialismo se articularam na disputa por recursos, mercados e poder."},{"topic_slug":"historia-revolucoes-industriais","prompt":"Trabalhadores organizam associa\u00e7\u00f5es para reivindicar redu\u00e7\u00e3o da jornada e melhores condi\u00e7\u00f5es. Esse processo evidencia:","difficulty":5,"correct_position":2,"options":["a inexist\u00eancia de conflitos nas f\u00e1bricas.","a forma\u00e7\u00e3o de movimentos e negocia\u00e7\u00f5es coletivas diante das rela\u00e7\u00f5es de trabalho.","o controle integral das f\u00e1bricas pelos trabalhadores.","o fim das mudan\u00e7as tecnol\u00f3gicas."],"explanation":"A organiza\u00e7\u00e3o coletiva foi uma resposta \u00e0s condi\u00e7\u00f5es de trabalho e \u00e0s desigualdades industriais."},{"topic_slug":"historia-ditadura-redemocratizacao","prompt":"O golpe de 1964 no Brasil iniciou um per\u00edodo marcado por:","difficulty":1,"correct_position":1,"options":["governos militares e restri\u00e7\u00f5es a direitos pol\u00edticos e civis.","amplia\u00e7\u00e3o cont\u00ednua de elei\u00e7\u00f5es diretas para presidente.","aus\u00eancia de censura e repress\u00e3o.","monarquia constitucional."],"explanation":"Ap\u00f3s o golpe, instalou-se uma ditadura militar com restri\u00e7\u00f5es e repress\u00e3o pol\u00edtica."},{"topic_slug":"historia-ditadura-redemocratizacao","prompt":"Durante a ditadura, a censura a jornais, m\u00fasicas e pe\u00e7as de teatro tinha como objetivo:","difficulty":2,"correct_position":3,"options":["garantir liberdade plena de cr\u00edtica.","ampliar a diversidade de opini\u00f5es nos meios de comunica\u00e7\u00e3o.","controlar a circula\u00e7\u00e3o de informa\u00e7\u00f5es e cr\u00edticas ao regime.","promover elei\u00e7\u00f5es competitivas."],"explanation":"A censura buscava limitar a circula\u00e7\u00e3o de cr\u00edticas e de informa\u00e7\u00f5es consideradas amea\u00e7adoras pelo regime."},{"topic_slug":"historia-ditadura-redemocratizacao","prompt":"A campanha Diretas J\u00e1, no in\u00edcio da d\u00e9cada de 1980, defendia:","difficulty":3,"correct_position":4,"options":["a volta da monarquia.","o fechamento do Congresso.","a suspens\u00e3o de elei\u00e7\u00f5es por tempo indeterminado.","a realiza\u00e7\u00e3o de elei\u00e7\u00f5es diretas para presidente."],"explanation":"A campanha mobilizou a sociedade pela volta da escolha direta do presidente."},{"topic_slug":"historia-ditadura-redemocratizacao","prompt":"A Constitui\u00e7\u00e3o brasileira de 1988 ficou conhecida como \u201cConstitui\u00e7\u00e3o Cidad\u00e3\u201d por ampliar e consolidar:","difficulty":4,"correct_position":2,"options":["o poder pol\u00edtico dos militares.","direitos e garantias fundamentais ap\u00f3s a ditadura.","a censura pr\u00e9via \u00e0 imprensa.","a proibi\u00e7\u00e3o de participa\u00e7\u00e3o social